def get_body_idxs(model):
    # Filter out hand and wrist joints
    body_idxs = []
    body_vel_idxs = []
    curr_idx = 0
    curr_vel_idx = 0
    for i in range(model.njnt):
        joint_name = mujoco.mj_id2name(model, mujoco.mjtObj.mjOBJ_JOINT, i)
        if joint_name.startswith("free_"):
            if joint_name == "free_base":
